(function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const student=()=>{try{return JSON.parse(localStorage.getItem('proexam_current_student')||'null')}catch(e){return null}};
const date=v=>{const d=new Date(v);return !v||isNaN(d)?'—':d.toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});};
const fit=(s,max=38)=>{s=String(s??'—');return s.length>max?s.slice(0,max-1)+'…':s};
function owns(s,u){
  if(!u)return false;
  const sid=String(u.userId||'').trim().toLowerCase();
  const cid=String(u.collegeCode||'').trim().toUpperCase();
  const sCollege=String(s.collegeCode||'').trim().toUpperCase();
  if(sCollege && cid && sCollege!==cid)return false;
  if(s.studentId && sid)return String(s.studentId).trim().toLowerCase()===sid;
  const semail=String(s.studentEmail||s.email||'').trim().toLowerCase();
  const uemail=String(u.email||'').trim().toLowerCase();
  if(semail && uemail && semail===uemail)return true;
  return String(s.studentName||'').trim().toLowerCase()===String(u.name||'').trim().toLowerCase();
}
function rows(sub,exam){
  const a=Array.isArray(sub.answers)?sub.answers:[];
  const k=String(exam.answerKey||'').split(',').map(x=>x.trim().toUpperCase());
  const saved=Array.isArray(sub.questionResults)?sub.questionResults:[];
  const checks=Array.isArray(sub.questionChecks)?sub.questionChecks:[];
  const auto=sub.gradingMode==='auto'||sub.status==='Auto-Graded';
  const hasManualQuestionChecks=saved.length>0||checks.length>0;
  const n=Math.max(Number(exam.numQuestions)||0,a.length,k.length,saved.length,checks.length);
  const mp=Number(exam.marksPerQuestion)||1;
  return Array.from({length:n},(_,i)=>{
    const reply=a[i]&&a[i]!=='-'?String(a[i]).toUpperCase():'—';
    const official=k[i]||'—';
    // Overall teacher-edited marks cannot tell us which individual answers were wrong.
    // Only show per-question correctness when it was actually saved or auto-graded.
    if(hasManualQuestionChecks){
      const item=saved[i];
      const known=item&&typeof item.correct==='boolean'?item.correct:(typeof checks[i]==='boolean'?checks[i]:null);
      return {no:i+1,reply,correct:official,marks:item&&Number.isFinite(Number(item.marks))?Number(item.marks):(known===true?mp:known===false?0:null),good:known,review:known===null};
    }
    if(!auto)return {no:i+1,reply,correct:official,marks:null,good:null,review:true};
    const good=reply!=='—'&&official!=='—'&&reply===official;
    return {no:i+1,reply,correct:official,marks:good?mp:0,good,review:false};
  });
}
function status(sub){
  if(sub.marks==null||sub.totalMarks==null||Number(sub.totalMarks)<=0)return 'PENDING';
  return Number(sub.marks)/Number(sub.totalMarks)*100>=40?'PASS':'FAIL';
}
function pdfEscape(s){return String(s??'').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[^\x20-\x7E]/g,'');}

// Exact ProExam web logo, compressed RGB pixels. It is embedded in the PDF so the download never depends on a network/CDN.
const LOGO_W=305, LOGO_H=80;
const LOGO_B64='';

function ascii(s){return new TextEncoder().encode(s);}
function joinBytes(parts){
  let n=0; for(const p of parts)n+=p.length;
  const out=new Uint8Array(n); let o=0;
  for(const p of parts){out.set(p,o);o+=p.length;}
  return out;
}
function pdfBytes(sub,exam,u){
  const PW=595, PH=842, M=36, CW=523;
  const C={navy:[31/255,63/255,145/255],blue:[47/255,103/255,216/255],ink:[32/255,42/255,58/255],muted:[102/255,117/255,138/255],light:[244/255,247/255,252/255],white:[1,1,1],border:[220/255,228/255,239/255],green:[24/255,183/255,122/255],red:[224/255,82/255,82/255]};
  const q=rows(sub,exam), full=Number(sub.totalMarks)||0, got=Number(sub.marks)||0;
  const pct=full?got/full*100:0, st=status(sub), dt=date(sub.submittedAt||Date.now());
  const pages=[]; let s='';
  const col=a=>a.map(v=>Number(v).toFixed(4)).join(' ');
  const R=(x,y,w,h,c)=>{s+=col(c)+' rg '+x+' '+(PH-y-h)+' '+w+' '+h+' re f\n';};
  const L=(x1,y1,x2,y2,c)=>{s+=col(c)+' RG 1 w '+x1+' '+(PH-y1)+' m '+x2+' '+(PH-y2)+' l S\n';};
  const T=(x,y,t,size,c,align='left')=>{
    t=pdfEscape(t); const w=t.length*size*.52;
    const xx=align==='center'?x-w/2:align==='right'?x-w:x;
    s+=col(c)+' rg BT /F1 '+size+' Tf '+xx.toFixed(2)+' '+(PH-y).toFixed(2)+' Td ('+t+') Tj ET\n';
  };
  const IMG=(x,y,w,h)=>{s+='q '+w+' 0 0 '+h+' '+x+' '+(PH-y-h)+' cm /Im1 Do Q\n';};
  const finish=()=>{pages.push(s);s='';};

  function header(pageNo){
    R(0,0,PW,PH,C.light);
    IMG(M,24,158,42);
    T(PW-M,48,'RESULT REPORT',10,C.navy,'right');
    T(PW-M,65,dt,8,C.muted,'right');
    L(M,78,PW-M,78,C.border);
    T(M,108,'Mock Objective Test - 2026',17,C.navy,'left');
    T(M,128,fit(exam.subject||'Objective Test',78),10.5,C.blue,'left');
    T(PW-M,108,'Page '+pageNo,8,C.muted,'right');
  }
  function details(){
    R(M,145,252,112,C.white); R(M+271,145,252,112,C.white);
    T(M+14,164,'STUDENT DETAILS',8.5,C.muted,'left'); T(M+285,164,'TEST DETAILS',8.5,C.muted,'left');
    L(M+14,171,M+238,171,C.border); L(M+285,171,PW-M-14,171,C.border);
    [['Name',u.name||sub.studentName||'—'],['Login ID',u.userId||sub.studentId||'—'],['College Code',u.collegeCode||sub.collegeCode||'—'],['Branch',u.branch||'—']].forEach((r,i)=>{T(M+14,190+i*18,r[0]+':',8.5,C.ink);T(M+72,190+i*18,fit(r[1],27),8.5,C.ink);});
    [['Marks / Question',String(exam.marksPerQuestion||1)+' Marks'],['Total Questions',String(exam.numQuestions||q.length)],['Duration',String(exam.duration||'—')+' Minutes'],['Attempted On',dt]].forEach((r,i)=>{T(M+285,190+i*18,r[0]+':',8.5,C.ink);T(M+380,190+i*18,fit(r[1],20),8.5,C.ink);});
  }
  function tableHead(y){
    const widths=[42,150,150,75,106], heads=['Q.','YOUR ANSWER','CORRECT ANSWER','MARKS','STATUS'];
    R(M,y,CW,32,C.blue); let x=M;
    heads.forEach((h,i)=>{T(x+widths[i]/2,y+21,h,8.5,C.white,'center');x+=widths[i];});
    return widths;
  }
  let pageNo=1; header(pageNo); details(); let y=279, widths=tableHead(y); y+=32;
  q.forEach((r,i)=>{
    if(y>735){finish();pageNo++;header(pageNo);y=145;widths=tableHead(y);y+=32;}
    const good=r.good===true; const bad=r.good===false; const review=r.review===true;
    R(M,y,CW,32,i%2?C.light:C.white); L(M,y+32,PW-M,y+32,C.border);
    let x=M;
    const vals=[String(r.no),r.reply==='—'?'Not Answered':'Option '+fit(r.reply,18),r.correct==='—'?'—':'Option '+fit(r.correct,18),r.marks===null||r.marks===undefined?'—':String(r.marks)+' / '+String(exam.marksPerQuestion||1),review?'REVIEW':good?'CORRECT':bad?'WRONG':'—'];
    vals.forEach((v,j)=>{const cc=j===4?(good?C.green:bad?C.red:C.muted):C.ink;T(x+widths[j]/2,y+21,v,8.3,cc,'center');x+=widths[j];});
    y+=32;
  });
  if(y>685){finish();pageNo++;header(pageNo);y=150;}
  const sy=y+10,sh=64,sw=(CW-9)/4;
  [['FULL MARKS',String(full)],['MARKS OBTAINED',String(got)],['PERCENTAGE',pct.toFixed(2)+'%'],['RESULT STATUS',st]].forEach((r,i)=>{
    const x=M+i*(sw+3);R(x,sy,sw,sh,C.white);T(x+sw/2,sy+23,r[0],7.2,C.muted,'center');T(x+sw/2,sy+48,r[1],13,i===3?(st==='PASS'?C.green:C.red):C.navy,'center');
  });
  T(M,815,'Generated by ProExam - Student Result Report',7,C.muted); T(PW-M,815,'Student Copy',7,C.muted,'right'); finish();

  // Build a real binary PDF. Offsets are byte offsets, and the logo is a proper Image XObject.
  const objects=[]; const add=b=>{objects.push(b);return objects.length;};
  const fontId=add(ascii('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'));
  const logoRaw=(()=>{const bin=atob(LOGO_B64);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a;})();
  const imageHeader=ascii('<< /Type /XObject /Subtype /Image /Width '+LOGO_W+' /Height '+LOGO_H+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /Length '+logoRaw.length+' >>\nstream\n');
  const imageFooter=ascii('\nendstream');
  const imageId=add(joinBytes([imageHeader,logoRaw,imageFooter]));
  const pagesId=add(new Uint8Array());
  const pageIds=[];
  for(const content of pages){
    const stream=ascii('<< /Length '+content.length+' >>\nstream\n'+content+'endstream');
    const streamId=add(stream);
    const pageId=add(ascii('<< /Type /Page /Parent '+pagesId+' 0 R /MediaBox [0 0 '+PW+' '+PH+'] /Resources << /Font << /F1 '+fontId+' 0 R >> /XObject << /Im1 '+imageId+' 0 R >> >> /Contents '+streamId+' 0 R >>'));
    pageIds.push(pageId);
  }
  objects[pagesId-1]=ascii('<< /Type /Pages /Kids ['+pageIds.map(id=>id+' 0 R').join(' ')+'] /Count '+pageIds.length+' >>');
  const catalogId=add(ascii('<< /Type /Catalog /Pages '+pagesId+' 0 R >>'));

  const pdfHeader=ascii('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  const chunks=[pdfHeader]; const offsets=[0]; let total=pdfHeader.length;
  for(let i=0;i<objects.length;i++){
    offsets.push(total);
    const pre=ascii((i+1)+' 0 obj\n'); const post=ascii('\nendobj\n');
    chunks.push(pre,objects[i],post); total+=pre.length+objects[i].length+post.length;
  }
  const xrefOffset=total;
  let xref='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n';
  for(let i=1;i<=objects.length;i++)xref+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
  xref+='trailer\n<< /Size '+(objects.length+1)+' /Root '+catalogId+' 0 R >>\nstartxref\n'+xrefOffset+'\n%%EOF';
  chunks.push(ascii(xref));
  return joinBytes(chunks);
}
window.downloadResultPdf=function(id){
  let url='';
  try{
    const u=student();
    if(!u){alert('Please login as a student first.');return false;}
    const sub=getSubmissions().find(x=>String(x.subId)===String(id));
    if(!sub||!owns(sub,u)){alert('This result is not available for your account.');return false;}
    const exam=getExamById(sub.examId);
    if(!exam){alert('Exam details are no longer available.');return false;}
    if(sub.marks==null||sub.totalMarks==null||Number(sub.totalMarks)<=0){alert('Your result is still under review.');return false;}

    // Build and validate the PDF before starting the download.
    const bytes=pdfBytes(sub,exam,u);
    if(!(bytes instanceof Uint8Array) || bytes.length < 100 || String.fromCharCode(bytes[0],bytes[1],bytes[2],bytes[3],bytes[4]) !== '%PDF-'){
      throw new Error('Generated PDF is invalid.');
    }
    const blob=new Blob([bytes],{type:'application/pdf'});
    url=URL.createObjectURL(blob);
    const filename='ProExam_'+String(u.userId||'Student').replace(/[^A-Za-z0-9_-]/g,'_')+'_Result.pdf';

    // Primary: native browser download.
    const a=document.createElement('a');
    a.href=url;
    a.download=filename;
    a.setAttribute('download',filename);
    a.rel='noopener';
    a.style.position='fixed'; a.style.left='-9999px'; a.style.width='1px'; a.style.height='1px';
    document.body.appendChild(a);
    a.click();

    // Fallback: show a real visible PDF link if the browser blocks programmatic downloads.
    setTimeout(()=>{
      try{
        if(document.body.contains(a)) a.remove();
        const old=document.getElementById('proexam-pdf-fallback');
        if(old) old.remove();
        const box=document.createElement('div');
        box.id='proexam-pdf-fallback';
        box.style.cssText='position:fixed;right:20px;bottom:20px;z-index:999999;background:#fff;border:1px solid #dbe3ef;border-radius:14px;padding:14px 16px;box-shadow:0 12px 40px rgba(15,23,42,.18);font:14px Arial,sans-serif;color:#1f2937;max-width:330px';
        box.innerHTML='<div style=\"font-weight:700;margin-bottom:8px\">Result PDF is ready</div><a id=\"proexam-pdf-open\" href=\"'+url+'\" download=\"'+filename+'\" style=\"display:inline-block;background:#2f67d8;color:#fff;text-decoration:none;padding:9px 13px;border-radius:9px;font-weight:700;margin-right:8px\">Download PDF</a><a href=\"'+url+'\" target=\"_blank\" rel=\"noopener\" style=\"color:#2f67d8;font-weight:700\">Open PDF</a><button id=\"proexam-pdf-close\" style=\"margin-left:8px;border:0;background:none;color:#64748b;cursor:pointer\">×</button>';
        document.body.appendChild(box);
        document.getElementById('proexam-pdf-close').onclick=()=>box.remove();
      }catch(e){console.error('PDF fallback error:',e);}
    },350);

    // Keep the object URL alive long enough for both native and fallback download.
    setTimeout(()=>{
      try{const box=document.getElementById('proexam-pdf-fallback'); if(!box){URL.revokeObjectURL(url);}}catch(e){}
    },120000);
    return true;
  }catch(err){
    console.error('Result PDF error:',err);
    if(url){try{URL.revokeObjectURL(url);}catch(e){}}
    alert('Unable to create the result PDF. Please try again.');
    return false;
  }
};

document.addEventListener('DOMContentLoaded',()=>{
  const u=student(); if(!u){location.href='../index.html';return;}
  const exams=getExams(); const examMap=new Map(exams.map(e=>[String(e.id),e]));
  const subs=getSubmissions().filter(s=>owns(s,u)); const tbody=document.getElementById('marks-table'); let html='';
  subs.sort((a,b)=>new Date(b.submittedAt||0)-new Date(a.submittedAt||0)).forEach(sub=>{
    const ex=examMap.get(String(sub.examId)); if(!ex)return;
    const graded=sub.marks!=null&&sub.totalMarks!=null&&Number(sub.totalMarks)>0; const pct=graded?(Number(sub.marks)/Number(sub.totalMarks)*100):0;
    const attemptTime=date(sub.submittedAt);
    const resultTime=date(sub.gradedAt||sub.resultPublishedAt||sub.publishedAt||(sub.gradingMode==='auto'?sub.submittedAt:null));
    html+=`<tr><td><strong class="result-title">${esc(ex.name||'Exam')}</strong><br><span class="result-sub">${esc(ex.subject||'Subject')}</span></td><td>${graded?`<strong style="color:var(--success);font-size:21px">${esc(sub.marks)}</strong> <span>/ ${esc(sub.totalMarks)}</span>`:'<span class="badge badge-warning">Pending</span>'}</td><td>${graded?`<span class="badge ${pct>=40?'badge-success':'badge-danger'}">${pct>=40?'✓ PASS':'✕ FAIL'}</span>`:'<span class="badge badge-warning">Pending Review</span>'}</td><td class="result-date"><strong>Submitted</strong><span>${esc(attemptTime)}</span></td><td class="result-date"><strong>${graded?'Published / Checked':'Not published'}</strong><span>${graded?esc(resultTime):'Awaiting evaluation'}</span></td><td>${esc(sub.teacherFeedback||(sub.gradingMode==='auto'?'Automatically evaluated':'Result checked by teacher'))}</td><td class="result-download">${graded?`<button type="button" class="btn btn-primary" onclick="downloadResultPdf('${esc(sub.subId)}')">⬇ Download PDF</button>`:'<button class="btn btn-outline" disabled>PDF after result</button>'}</td></tr>`;
  });
  if(!html)html='<tr><td colspan="5" class="result-empty">No completed results are available for your account yet.</td></tr>';
  tbody.innerHTML=html;
});
})();
